import {el} from './dom.js';import {t} from './locales.js';import {estimateHarvest,causality} from './care.js';
export function setupInspect(){const dialog=/** @type {HTMLDialogElement} */(el('inspect-dialog'));el('close-inspect').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{const button=/** @type {HTMLButtonElement|null} */(document.querySelector('#inspect'));button?.focus();});}
/** @param {import('./engine.js').State} state @param {number|null} id */
export function renderInspect(state,id){const plot=state.plots.find(p=>p.id===id);if(!plot)return;el('inspect-heading').textContent=t('plot')+' '+(plot.id+1);const host=el('inspect-values');host.replaceChildren();const estimate=estimateHarvest(state,plot);const values=[['inspectMoisture',(100*plot.soilWaterMm/plot.soilCapacityMm).toFixed(1)+'%','inspect-moisture'],['inspectWater',plot.soilWaterMm.toFixed(1)+' / '+plot.soilCapacityMm+' mm','inspect-water-mm'],['inspectApplied',plot.waterAppliedMm.toFixed(1)+' mm','inspect-applied'],['inspectWeather',t(state.weather),'inspect-weather'],['inspectGrowth',plot.crop?Math.floor(plot.crop.progress*100)+'%':'—','inspect-growth'],['inspectQuality',plot.crop?Math.round(plot.crop.quality*100)+'%':'—','inspect-quality'],['inspectCost',plot.careCost.toFixed(1)+' '+t('coins'),'inspect-cost'],['inspectHarvest',estimate?'≈'+estimate.hours+' '+t('gameHours')+' · '+estimate.quantity+' '+t('produceUnits')+' · '+estimate.revenue+' '+t('coins'):'—','inspect-estimate']];for(const [label,value,key]of values){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=t(label);dd.textContent=value;dd.id=key;host.append(dt,dd);}}
/** @param {import('./engine.js').State} state @param {number} id */
export function showInspect(state,id){renderInspect(state,id);renderReasons(state,id);/** @type {HTMLDialogElement} */(el('inspect-dialog')).showModal();}
/** @param {import('./engine.js').State} state @param {number|null} id */
export function renderReasons(state,id){const plot=state.plots.find(p=>p.id===id);if(!plot)return;const list=el('inspect-reasons');list.replaceChildren();for(const key of causality(state,plot)){const item=document.createElement('li');item.textContent=t(key);list.append(item);}}
